-- Class notes synopsis batch 9: Cranberry through Dill

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cranberry</strong> is an <strong>antioxidant</strong> that inhibits <strong>H. pylori</strong> (<strong>peptic ulcer</strong>); as an antioxidant for <strong>rheumatoid arthritis</strong>, buffering oxidative waste in the blood. Cranberry juice for <strong>UTI</strong> support and <strong>ear health</strong> (TCM connects kidneys to ears; drink sufficient fluids, especially water).$$
WHERE common_name = 'Cranberry';

