UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Damiana</strong> is a <strong>warming</strong>, <strong>bitter</strong>, <strong>carminative</strong>, <strong>aphrodisiac</strong>, and <strong>anxiolytic nervine</strong> herb with a <strong>heating</strong> energetic quality - "teaches embodiment" and connects the hormonal and mind-body axis. Specifically indicated for <strong>stagnant depression</strong> (hormonal connection to mood), <strong>thyroid-induced depression</strong> (hypothyroidism), and thyroid protocol support. A <strong>carminative</strong> for <strong>hypochlorhydria</strong>; digestive and <strong>liver</strong> support. An <strong>aphrodisiac</strong> for <strong>erectile dysfunction</strong>. <strong>Anxiolytic nervine</strong> for <strong>anxiety</strong>. For <strong>female reproductive deficiency</strong>: stimulates the HPA. A warming herb for <strong>poor circulation</strong> and <strong>stagnation</strong>. A key herb in the herbal support strategy for <strong>cancer</strong> care. In a euphoric nervine formula to wean off cannabis for a blood sugar case study patient.$$
WHERE common_name = 'Damiana';

-- Dandelion id=122: root
UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Dandelion</strong> root (Taraxacum officinale) is a <strong>cooling</strong>, <strong>bitter</strong>, <strong>hepatic</strong>, <strong>alterative</strong>, <strong>choleretic</strong>, and <strong>GI tonic</strong> herb - slightly sweet, the least bitter of the bitters. Specifically indicated for: <strong>jaundice</strong>, pain in the <strong>gallbladder</strong>, digestive disturbance, headache due to liver issues (forehead), tenderness in the liver, coated tongue. Mostly <strong>choleretic</strong> - increases bile production by the liver rather than forcing bile release; safer for patients with gallstone risk compared to strong cholagogues; for <strong>liver excess</strong>: stimulates bile secretion without stimulating liver metabolism. Stimulates digestive secretions including HCL, pancreatic juices, and bile; a <strong>cooling bitter</strong> for <strong>hypochlorhydria</strong>; a key bitter in the EP all-purpose bitter formula; "bitters before mealtime: dandelion root or leaf, artichoke leaf." Works through the bowel, kidney, skin, and liver to detoxify and shift the body toward health; a <strong>liver alterative</strong> for <strong>hot constitution</strong> alongside Chicory, Sarsaparilla, Sassafras, Licorice, and Astragalus; alterative for <strong>wet constitution</strong>; <strong>metabolic support</strong> for <strong>perimenopause</strong>; for <strong>skin excess</strong> (toxin buildup) alongside <a href="?herb=22"><strong>Burdock</strong></a> root. Reduces sodium (potassium-sparing) - useful when hormones like Aldosterone, Estrogen, and Cortisol encourage kidneys to retain sodium and water. Liver support: metabolises fats and hormones; for <strong>liver disease</strong>, <strong>mastitis</strong>, <strong>hepatitis</strong>, <strong>pancreatitis</strong>. "About the liver - stacking reproductive symptoms indicates focusing on the liver first." <strong>Alterative</strong> and digestive bitter for <strong>rheumatoid arthritis</strong>; alterative for accumulation with aging. Part of detox protocol for <strong>chemical sensitivity</strong>; for lighter ongoing liver support vs. <a href="?herb=206"><strong>Milk Thistle</strong></a> extract when there's a history of chronic toxin exposure. Prebiotic: contains <strong>inulin</strong> alongside <a href="?herb=22"><strong>Burdock</strong></a> and Chicory for microbiome diversity. For <strong>constipation during pregnancy</strong> (second step if <a href="?herb=45"><strong>Marshmallow</strong></a> root is not working). <strong>Dandelion flower oil</strong> (mapped to root record): good for moving through deep-seated emotional blockages; breaks through physical congestion and lethargy. Can replace coffee with toasted Dandelion and <a href="?herb=22"><strong>Burdock</strong></a>; seasonal nourishing root to embrace as greens and roots shift in fall. Dosage: 2-4 mL twice daily for liver support, GI tract stimulation, and bile flow; also for iron absorption support alongside <a href="?herb=37"><strong>Yellow Dock</strong></a>. In liver tea formula (2P <a href="?herb=22"><strong>Burdock</strong></a>, 2P <a href="?herb=225"><strong>Astragalus</strong></a>, 1P Dandelion, 1P orange peel, 1P <a href="?herb=76"><strong>Fennel</strong></a>, 1P <a href="?herb=78"><strong>Licorice</strong></a>); in colic tincture (2 parts) with <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=76"><strong>Fennel</strong></a>, and <a href="?herb=55"><strong>Peppermint</strong></a> (dosing: 3-4 drops for 2-3 months, 4-6 drops for 3-4 months, 6-8 drops for 4+ months); with <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, and fresh <a href="?herb=124"><strong>Ginger</strong></a> for bloating and water retention; with <a href="?herb=1548"><strong>Wolfberry Fruit</strong></a> for bitter liver support and nourishment; with <a href="?herb=28"><strong>Cleavers</strong></a> and <a href="?herb=22"><strong>Burdock</strong></a> as poultice for <strong>breast cysts</strong>.$$
WHERE id = 122;

-- Dandelion id=1648: leaf
UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Dandelion</strong> leaf (Taraxacum officinale) is a <strong>cooling</strong>, <strong>drying</strong>, <strong>bitter</strong>, <strong>diuretic</strong>, <strong>alterative</strong>, <strong>nutritive</strong>, and <strong>liver-supportive</strong> (stimulates bile) herb and mild digestive tonic. A notable exception among diuretics - contains so many minerals it leaves your body with a net gain; minerals = longer hot infusion; also prepared as cold infusion for mineral extraction. As a <strong>diuretic</strong>: removes excess water and sodium; supports <strong>kidneys</strong> by flushing out microbes and proteins; contains <strong>potassium</strong>; a <strong>cardiovascular</strong> diuretic; try to get off Lasix (furosemide) and onto Dandelion leaf especially for <strong>edema</strong>. <strong>Caution: diuretic action could worsen incontinence - use with awareness in urinary patients.</strong> <strong>Alterative</strong> and diuretic for <strong>rheumatoid arthritis</strong> (drains synovial fluid). For <strong>kidney excess</strong> as a diuretic cooler. In Urinary System Support glycerite with <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=22"><strong>Burdock</strong></a>, and <a href="?herb=55"><strong>Peppermint</strong></a> (to move water and remove waste); in kidney/bladder tonics with <a href="?herb=58"><strong>Goldenrod</strong></a>, <a href="?herb=28"><strong>Cleavers</strong></a>, <a href="?herb=118"><strong>Bladderwrack</strong></a>, and watermelon in season; in nutritive oxymel with <a href="?herb=43"><strong>Nettle</strong></a>, seaweed, <a href="?herb=178"><strong>Oat</strong></a> straw, and <a href="?herb=885"><strong>Alfalfa</strong></a>. Pet dosing: 5 drops per 1 cup water for small dog/cat; 10 drops per cup for medium; 20 drops per quart for large.$$
WHERE id = 1648;

